answer:
1D Array: Stores linear list of elements.
Syntax: type name[size];

2D Array: Stores grid of elements in rows and columns.
Syntax: type name[rows][cols];

Matrix Addition Program:
#include <iostream>
using namespace std;
int main() {
    int a[2][2], b[2][2], sum[2][2];
    cout << "Enter 4 elements of matrix A: ";
    for(int i=0; i<2; i++) for(int j=0; j<2; j++) cin >> a[i][j];
    cout << "Enter 4 elements of matrix B: ";
    for(int i=0; i<2; i++) for(int j=0; j<2; j++) cin >> b[i][j];
    for(int i=0; i<2; i++) for(int j=0; j<2; j++) sum[i][j] = a[i][j] + b[i][j];
    cout << "Sum Matrix:\n";
    for(int i=0; i<2; i++) {
        for(int j=0; j<2; j++) cout << sum[i][j] << " ";
        cout << endl;
    }
    return 0;
}

