answer:
A structure allows defining a composite data type comprising heterogeneous fields.

Complete Program:
#include <iostream>
using namespace std;
struct Employee {
    int emp_id;
    char name[30];
    float salary;
};
int main() {
    Employee e1 = {101, "Ramesh", 45000.50}; // Initializing structure
    Employee e2;
    cout << "Enter Employee 2 ID, Name, Salary: ";
    cin >> e2.emp_id >> e2.name >> e2.salary;
    cout << "\n--- Employee Details ---\n";
    cout << "E1: ID=" << e1.emp_id << ", Name=" << e1.name << ", Salary=" << e1.salary << endl;
    cout << "E2: ID=" << e2.emp_id << ", Name=" << e2.name << ", Salary=" << e2.salary << endl;
    return 0;
}

